// Promise-driven UI widgets (textbox, menus, party, bag, dex, shop).
// Game loop calls UI.update()/UI.draw() every frame; async game scripts await
// UI.message(...) / UI.menu(...) etc.
window.UI = (() => {
  const W = 240, H = 160;
  const stack = [];
  const busy = () => stack.length > 0;

  function push(widget) { stack.push(widget); return widget.done; }
  function pop(widget) {
    const i = stack.indexOf(widget);
    if (i >= 0) stack.splice(i, 1);
  }

  // Wrap text to maxChars per line, respecting explicit \n.
  function wrap(str, maxChars = 36) {
    const out = [];
    for (const para of String(str).split('\n')) {
      let line = '';
      for (const word of para.split(' ')) {
        if (line && (line + ' ' + word).length > maxChars) { out.push(line); line = word; }
        else line = line ? line + ' ' + word : word;
      }
      out.push(line);
    }
    return out;
  }

  // ---- Textbox -------------------------------------------------------------
  function message(text, { sticky = false } = {}) {
    let resolve;
    const done = new Promise(r => resolve = r);
    const lines = wrap(text);
    const w = {
      kind: 'msg',
      page: 0, chars: 0, sticky,
      done,
      update() {
        const pageLines = lines.slice(this.page, this.page + 2);
        const total = pageLines.join('').length;
        if (this.chars < total) {
          this.chars += Input.held('a') || Input.held('b') ? 3 : 1.2;
          if (this.chars > total) this.chars = total;
          return;
        }
        if (this.page + 2 < lines.length) {
          if (Input.press('a') || Input.press('b')) { Audio2.beep(); this.page += 2; this.chars = 0; }
        } else if (sticky) {
          pop(w); resolve(); // leave box on screen via Game's lastMsg if needed
        } else if (Input.press('a') || Input.press('b')) {
          Audio2.beep(); pop(w); resolve();
        }
      },
      draw(ctx) {
        drawTextboxFrame(ctx);
        const pageLines = lines.slice(this.page, this.page + 2);
        let remaining = Math.floor(this.chars);
        for (let i = 0; i < pageLines.length; i++) {
          const show = pageLines[i].slice(0, Math.max(0, remaining));
          remaining -= pageLines[i].length;
          Gfx.text(ctx, show, 10, 124 + i * 14);
        }
        const total = pageLines.join('').length;
        if (this.chars >= total && (this.page + 2 < lines.length || !sticky)) {
          if ((performance.now() / 300 | 0) % 2) Gfx.text(ctx, '>', 226, 146, '#e05048');
        }
      },
    };
    return push(w);
  }

  function drawTextboxFrame(ctx) { Gfx.frame(ctx, 0, 112, W, 48); }

  // ---- Menu ----------------------------------------------------------------
  // opts: array of strings. Returns index, or -1 if cancellable & B pressed.
  function menu(opts, { x, y, w, cancel = true, startIdx = 0 } = {}) {
    let resolve;
    const done = new Promise(r => resolve = r);
    const width = w ?? Math.max(...opts.map(o => Gfx.textWidth(o))) + 22;
    const height = opts.length * 14 + 12;
    const mx = x ?? W - width - 2, my = y ?? 2;
    const widget = {
      kind: 'menu', idx: startIdx, done,
      update() {
        if (Input.press('up')) { this.idx = (this.idx + opts.length - 1) % opts.length; Audio2.beep(); }
        if (Input.press('down')) { this.idx = (this.idx + 1) % opts.length; Audio2.beep(); }
        if (Input.press('a')) { Audio2.select(); pop(widget); resolve(this.idx); }
        else if (cancel && Input.press('b')) { Audio2.beep(); pop(widget); resolve(-1); }
      },
      draw(ctx) {
        Gfx.frame(ctx, mx, my, width, height);
        opts.forEach((o, i) => {
          Gfx.text(ctx, o, mx + 14, my + 7 + i * 14);
          if (i === this.idx) Gfx.text(ctx, '>', mx + 6, my + 7 + i * 14, '#e05048');
        });
      },
    };
    return push(widget);
  }

  async function confirm(text) {
    message(text, { sticky: true });
    const r = await menu(['YES', 'NO'], { x: 170, y: 64 });
    clearSticky();
    return r === 0;
  }

  function clearSticky() { /* sticky messages already popped; box vanishes next frame */ }

  // ---- Party screen --------------------------------------------------------
  // mode: 'view' | 'select'. Returns index or -1.
  function party(team, mode = 'view', title = 'CHOOSE A POKéMON.') {
    let resolve;
    const done = new Promise(r => resolve = r);
    const widget = {
      kind: 'party', idx: 0, done,
      update() {
        if (Input.press('up')) { this.idx = (this.idx + team.length - 1) % team.length; Audio2.beep(); }
        if (Input.press('down')) { this.idx = (this.idx + 1) % team.length; Audio2.beep(); }
        if (Input.press('a')) { Audio2.select(); pop(widget); resolve(this.idx); }
        else if (Input.press('b')) { Audio2.beep(); pop(widget); resolve(-1); }
      },
      draw(ctx) {
        ctx.fillStyle = '#88c8a8'; ctx.fillRect(0, 0, W, H);
        team.forEach((mon, i) => {
          const y = 4 + i * 22;
          Gfx.frame(ctx, 4, y, 232, 21);
          const sp = Pkmn.species(mon);
          const img = Gfx.monSprite(mon.id, 'front');
          if (img.complete) ctx.drawImage(img, 8, 16, 48, 32, 8, y + 2, 24, 16);
          Gfx.text(ctx, Pkmn.dname(mon), 36, y + 4);
          Gfx.text(ctx, 'LV' + mon.level, 36, y + 12, '#586068');
          Gfx.text(ctx, mon.hp + '/' + mon.stats.hp, 150, y + 12, '#586068');
          Gfx.hpBar(ctx, 150, y + 6, 60, mon.hp, mon.stats.hp);
          if (mon.status) Gfx.text(ctx, mon.status.toUpperCase(), 110, y + 12, '#c05048');
          if (mon.hp <= 0) Gfx.text(ctx, 'FNT', 110, y + 12, '#c05048');
          if (i === this.idx) {
            ctx.strokeStyle = '#e05048'; ctx.lineWidth = 2;
            ctx.strokeRect(5, y + 1, 230, 19);
          }
        });
        Gfx.frame(ctx, 4, 138, 232, 20);
        Gfx.text(ctx, title, 10, 144);
      },
    };
    return push(widget);
  }

  // ---- Bag -----------------------------------------------------------------
  // Returns item id or null. inBattle filters usable items.
  function bag(inventory, { battle = false } = {}) {
    let resolve;
    const done = new Promise(r => resolve = r);
    const entries = () => Object.entries(inventory).filter(([, n]) => n > 0);
    const widget = {
      kind: 'bag', idx: 0, done,
      update() {
        const es = entries();
        if (!es.length) { pop(widget); resolve(null); return; }
        if (this.idx >= es.length) this.idx = es.length - 1;
        if (Input.press('up')) { this.idx = (this.idx + es.length - 1) % es.length; Audio2.beep(); }
        if (Input.press('down')) { this.idx = (this.idx + 1) % es.length; Audio2.beep(); }
        if (Input.press('a')) { Audio2.select(); pop(widget); resolve(es[this.idx][0]); }
        else if (Input.press('b')) { Audio2.beep(); pop(widget); resolve(null); }
      },
      draw(ctx) {
        ctx.fillStyle = '#d8b868'; ctx.fillRect(0, 0, W, H);
        Gfx.frame(ctx, 4, 4, 232, 18);
        Gfx.text(ctx, 'BAG', 12, 10);
        Gfx.frame(ctx, 4, 26, 232, 128);
        const es = entries();
        if (!es.length) Gfx.text(ctx, 'The BAG is empty.', 14, 36);
        const first = Math.max(0, Math.min(this.idx - 3, es.length - 8));
        es.slice(first, first + 8).forEach(([id, n], row) => {
          const i = first + row, y = 33 + row * 14;
          const item = Pkmn.ITEMS[id];
          Gfx.text(ctx, item.name, 24, y);
          Gfx.text(ctx, 'x' + n, 190, y, '#586068');
          if (i === this.idx) Gfx.text(ctx, '>', 14, y, '#e05048');
        });
      },
    };
    return push(widget);
  }

  // ---- Shop ----------------------------------------------------------------
  async function shop(stock, save) {
    await message('Welcome! How may I\nhelp you?');
    while (true) {
      const names = stock.map(id => Pkmn.ITEMS[id].name + ' $' + Pkmn.ITEMS[id].price);
      const moneyBox = {
        kind: 'money', done: new Promise(() => {}),
        update() {}, draw(ctx) { Gfx.frame(ctx, 2, 2, 90, 18); Gfx.text(ctx, '$' + save.money, 8, 8); },
      };
      stack.push(moneyBox);
      const pick = await menu([...names, 'CANCEL'], { x: 96, y: 2, w: 142, cancel: true });
      pop(moneyBox);
      if (pick < 0 || pick === stock.length) break;
      const id = stock[pick], item = Pkmn.ITEMS[id];
      if (save.money < item.price) { await message("You don't have enough\nmoney."); continue; }
      const maxQ = Math.min(9, Math.floor(save.money / item.price));
      const q = await menu(Array.from({ length: maxQ }, (_, i) => 'x' + (i + 1) + '  $' + item.price * (i + 1)), { x: 140, y: 40 });
      if (q < 0) continue;
      save.money -= item.price * (q + 1);
      save.bag[id] = (save.bag[id] ?? 0) + q + 1;
      Audio2.select();
      await message('Here you are!\nThank you!');
    }
    await message('Please come again!');
  }

  // ---- Pokédex -------------------------------------------------------------
  function pokedex(save) {
    let resolve;
    const done = new Promise(r => resolve = r);
    const widget = {
      kind: 'dex', idx: 0, done,
      update() {
        if (Input.press('up')) this.idx = (this.idx + 150) % 151;
        if (Input.press('down')) this.idx = (this.idx + 1) % 151;
        if (Input.press('left')) this.idx = (this.idx + 151 - 10) % 151;
        if (Input.press('right')) this.idx = (this.idx + 10) % 151;
        if (Input.press('b') || Input.press('a')) { Audio2.beep(); pop(widget); resolve(); }
      },
      draw(ctx) {
        ctx.fillStyle = '#c84838'; ctx.fillRect(0, 0, W, H);
        Gfx.frame(ctx, 4, 4, 110, 18);
        const seen = Object.keys(save.seen).length, caught = Object.keys(save.caught).length;
        Gfx.text(ctx, `SEEN ${seen} OWN ${caught}`, 9, 10);
        Gfx.frame(ctx, 4, 26, 110, 128);
        const first = Math.max(0, Math.min(this.idx - 4, 151 - 9));
        for (let row = 0; row < 9; row++) {
          const id = first + row + 1;
          if (id > 151) break;
          const y = 32 + row * 13.5;
          const known = save.seen[id] || save.caught[id];
          Gfx.text(ctx, String(id).padStart(3, '0'), 12, y, '#586068');
          Gfx.text(ctx, save.caught[id] ? '*' : ' ', 34, y, '#e05048');
          Gfx.text(ctx, known ? POKEDEX[id].displayName.toUpperCase() : '-----', 44, y);
          if (id === this.idx + 1) Gfx.text(ctx, '>', 5, y, '#f8d020');
        }
        Gfx.frame(ctx, 118, 26, 118, 128);
        const selId = this.idx + 1;
        if (save.seen[selId] || save.caught[selId]) {
          const img = Gfx.monSprite(selId, 'front');
          if (img.complete) ctx.drawImage(img, 145, 40, 64, 64);
          const sp = POKEDEX[selId];
          Gfx.text(ctx, sp.displayName.toUpperCase(), 130, 110);
          Gfx.text(ctx, sp.types.map(t => t.toUpperCase()).join('/'), 130, 122, '#586068');
          if (save.caught[selId]) Gfx.text(ctx, 'CAUGHT!', 130, 134, '#e05048');
        } else {
          Gfx.text(ctx, '?', 172, 66, '#883830');
        }
      },
    };
    return push(widget);
  }

  function update() {
    if (stack.length) stack[stack.length - 1].update();
  }
  function draw(ctx) {
    for (const w of stack) w.draw(ctx);
  }

  return { busy, message, menu, confirm, party, bag, shop, pokedex, update, draw, wrap, drawTextboxFrame };
})();
